 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != bg and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            components.append(comp)
    stamp_comp = max(components, key=len)
    stamp_cells = set(stamp_comp)
    r0, r1 = min(r for r,c in stamp_comp), max(r for r,c in stamp_comp)
    c0, c1 = min(c for r,c in stamp_comp), max(c for r,c in stamp_comp)
    stamp = [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    # Isolated single-cell objects are the repeat locations; select their shared color.
    dot_colors = Counter(grid[comp[0][0]][comp[0][1]] for comp in components if len(comp) == 1)
    marker = dot_colors.most_common(1)[0][0]
    out = [row[:] for row in grid]
    ar, ac = len(stamp)//2, len(stamp[0])//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r,c) not in stamp_cells:
                for i in range(len(stamp)):
                    for j in range(len(stamp[0])):
                        rr, cc = r+i-ar, c+j-ac
                        if 0 <= rr < h and 0 <= cc < w and stamp[i][j] != bg:
                            out[rr][cc] = stamp[i][j]
    return out
